class Car:
    def __init__(self, brand):
        self.brand = brand

c = Car("Audi")
print(c.brand)

class Dog:
    def speak(self):
        return "Vau"

d = Dog()
print(d.speak())

class Animal:
    def move(self): print("Mozog", end="")

class Bird(Animal):
    def move(self): 
        super().move()
        print("Repül", end="")

b = Bird()
b.move()

class Square:
    def __init__(self, a): self.a = a
    @property
    def area(self): return self.a * self.a

s = Square(4)
print(s.area)
